import re
from datetime import datetime, timedelta
from collections import defaultdict

SSHD = re.compile(r"^(?P<ts>\S+) (?P<host>\S+) sshd\[\d+\]: Failed password for (invalid user )?(?P<user>\S+) from (?P<ip>\S+)")

def from_sshd(line):
    m = SSHD.match(line)
    return m and {"ts": m["ts"], "source": "linux-sshd", "outcome": "failure",
                  "user": m["user"], "src_ip": m["ip"]}

def from_cloudtrail(rec):
    ok = rec["responseElements"].get("ConsoleLogin") == "Success"
    return {"ts": rec["eventTime"], "source": "aws-cloudtrail",
            "outcome": "success" if ok else "failure",
            "user": rec["userIdentity"].get("userName"), "src_ip": rec["sourceIPAddress"]}

ssh = [f"2026-11-26T09:00:{s:02d}Z bastion-01 sshd[811]: Failed password for root from 203.0.113.7 port 5{s} ssh2" for s in (1, 9, 17, 30, 44)]
ct = [{"eventTime": "2026-11-26T09:00:50Z", "userIdentity": {"userName": "ops-kim"},
       "sourceIPAddress": "203.0.113.7", "responseElements": {"ConsoleLogin": "Success"}}]

events = sorted([from_sshd(l) for l in ssh] + [from_cloudtrail(r) for r in ct], key=lambda e: e["ts"])
fails = defaultdict(list)
for e in events:
    t = datetime.fromisoformat(e["ts"].replace("Z", "+00:00"))
    if e["outcome"] == "failure":
        fails[e["src_ip"]].append(t)
    elif len([f for f in fails[e["src_ip"]] if t - f <= timedelta(seconds=60)]) >= 5:
        print(f"ALERT {e['src_ip']}: 실패 5회 뒤 {e['source']} 로그인 성공 (user={e['user']})")

# 출력: ALERT 203.0.113.7: 실패 5회 뒤 aws-cloudtrail 로그인 성공 (user=ops-kim)
